onKey(" ", async () => {
  play("beep");
  say("Hi!", 2);
  // wave the left arm
  await part("left arm").turnTo(150);
  await part("left arm").wiggle(3);
  await part("left arm").turnTo(0);
  // head over to the tree
  await goTo(thing("tree-3"), 7);
});

forever(async () => {
  const seen = await look(8);
  if (seen && is(seen, "red")) {
    play("honk");
    await move(-5, 7); // back up
  }
  await wait(0.2);
});

const rainbow = ["red", "orange", "yellow", "green", "blue", "purple"];

onKey("f", async () => {
  // Turn off gravity so everything floats
  gravity(0);
  play("magic");
  say("Everything is floating!", 2);
  await wait(5);

  // Gravity back on
  gravity(1);
  play("slide");

  // Drop a bunch of rainbow bricks
  for (let i = 0; i < 18; i++) {
    spawn({ color: rainbow[i % rainbow.length], size: "2x2", at: place(random(-12, 12), random(-12, 12)) });
    await wait(0.15);
  }
});
